var e={"where.project":`Proyecto`,"where.topic":`Tema`,"where.projectHelp":`Un proyecto agrupa los temas de un mismo asunto. Su CLAUDE.md y su memoria se aplican a todos sus temas.`,"where.topicHelp":`El tema es la carpeta de trabajo de esta sesión: Harness trabaja ahí con el CLAUDE.md y la memoria del tema, además de los del proyecto y los globales.`,"where.move":`Haz clic para mover esta sesión a otro tema.`,"where.agent":`Agente`,"where.agentHelp":`Esta sesión se ejecuta en la carpeta de un agente: Claude trabaja allí con el rol y la memoria del agente, además de los del tema, del proyecto y los globales.`};export{e as default};